        content:
            'فیلم کوتاه «تنهایی ماه» (The Loneliness Of The Moon) به کارگردانی پژهان ضیائیان، در تازه‌ترین ایستگاه بین‌المللی خود، به بخش رسمی پنجمین دوره جشنواره بین‌المللی فیلم کوتاه Golden Bridge Istanbul در کشور ترکیه راه یافت. این خبر بار دیگر نام یک فیلم کوتاه ایرانی را در فهرست آثار پذیرفته‌شده یکی از رویدادهای مستقل سینمایی ترکیه ثبت کرد.\n\n' +
            'جشنواره Golden Bridge Istanbul Short Film Festival یکی از رویدادهای مستقل سینمایی ترکیه است که با هدف معرفی فیلمسازان نوظهور از سراسر جهان برگزار می‌شود. این جشنواره هر سال میزبان فیلم‌های کوتاه و بلند مستقل در ژانرهای گوناگون است و آثار راه‌یافته توسط هیأتی از داوران دانشگاهی مورد ارزیابی قرار می‌گیرند؛ ساختاری که به گفته برگزارکنندگان، هدف آن بالا نگه‌داشتن سطح کیفی داوری و توجه به جنبه‌های آموزشی و پژوهشی آثار مستقل است.\n\n' +
            'راه‌یابی «تنهایی ماه» به پنجمین دوره این جشنواره، در ادامه روندی قرار می‌گیرد که طی آن فیلم‌های کوتاه ایرانی در سال‌های اخیر توانسته‌اند حضوری پیوسته در رویدادهای سینمایی ترکیه داشته باشند؛ کشوری که به‌واسطه هم‌جواری جغرافیایی و اشتراکات فرهنگی، همواره یکی از مقصدهای مورد توجه فیلمسازان مستقل ایرانی برای معرفی آثارشان بوده است.\n\n' +
            'تیم مستر شورت‌فیلم مسیر حضور بین‌المللی «تنهایی ماه» و اخبار مربوط به نمایش آن در جشنواره Golden Bridge Istanbul را در همین بخش وبلاگ دنبال و منتشر خواهد کرد.',
        date: '1405-05-05',
