        content:
            'فیلم کوتاه «بی‌ماری» (Taboophen) به نویسندگی و کارگردانی محمد نعیم اسماعیلی، در سیزدهمین دوره Zambia Short Film Festival موفق به کسب عنوان بهترین فیلم کوتاه بین‌المللی شد.\n\n' +
            'سیزدهمین دوره جشنواره فیلم کوتاه زامبیا با عنوان Frames of Peace از ۱ تا ۵ سپتامبر ۲۰۲۶ در شهر لوساکا، زامبیا برگزار شد. این جشنواره با هدف نمایش آثار کوتاه ملی و بین‌المللی و ایجاد بستری برای تبادل فرهنگی و سینمایی برگزار می‌شود.\n\n' +
            '«بی‌ماری» همچنین در هفتمین حضور جشنواره‌ای خود به نهمین دوره Independent Shorts Awards International Film Festival راه یافت؛ جشنواره‌ای که در لس‌آنجلس برگزار می‌شود و در سال ۲۰۲۶ نهمین سال فعالیت خود را پشت سر می‌گذارد.',
