        category: 'سینمای جهان',
        summary: 'فیلم «فیورد» به کارگردانی کریستین مونجیو، فیلمساز رومانیایی، جایزه نخل طلا را از هفتاد و نهمین جشنواره فیلم کن دریافت کرد؛ دومین نخل طلای او پس از «۴ ماه، ۳ هفته و ۲ روز» در سال ۲۰۰۷.',
        content:
            'هیئت داوران هفتاد و نهمین جشنواره فیلم کن به ریاست پارک چان-ووک، کارگردان کره‌ای، جایزه نخل طلا را به فیلم «فیورد» ساخته کریستین مونجیو اهدا کرد؛ درامی درباره یک زوج رومانیایی-نروژی که با نقل مکان به زادگاه همسر در نروژ با چالش‌های تازه‌ای روبه‌رو می‌شوند. مونجیو با این جایزه، دهمین کارگردانی شد که برای دومین‌بار نخل طلا می‌گیرد؛ افتخاری که پیش‌تر با فیلم «۴ ماه، ۳ هفته و ۲ روز» در سال ۲۰۰۷ نصیبش شده بود.\n\n' +
            'این جایزه هفتمین نخل طلای متوالی برای شرکت پخش نئون بود؛ روندی که از فیلم «انگل» در سال ۲۰۱۹ آغاز شده است. جشنواره کن امسال از ۱۲ تا ۲۳ مه ۲۰۲۶ برگزار شد و ۲۲ فیلم در بخش رقابتی اصلی آن حضور داشتند، از جمله آثاری از پدرو آلمودوار، آیرا زاکس، لاسلو نمش و اصغر فرهادی.',
