        summary: 'شصت‌وچهارمین جشنواره فیلم نیویورک با نمایش افتتاحیه «ببر کاغذی» ساخته جیمز گری، با بازی آدام درایور، مایلز تلر و اسکارلت جوهانسون، آغاز به کار کرد.',
        content:
            'شصت‌وچهارمین جشنواره فیلم نیویورک، از رویدادهای معتبر سینمایی آمریکا که زیر نظر مرکز فیلم لینکلن برگزار می‌شود، جمعه ۲۵ سپتامبر ۲۰۲۶ با نمایش افتتاحیه فیلم «ببر کاغذی» (Paper Tiger) ساخته جیمز گری در تالار آلیس تولی آغاز به کار کرد. این فیلم که پیش از این در بخش رقابتی جشنواره کن نمایش داده شده بود، داستان دو برادر در نیویورک دهه ۱۹۸۰ را روایت می‌کند که درگیر معامله‌ای با مافیای روسیه می‌شوند. این چهارمین باری است که یکی از آثار جیمز گری در جشنواره فیلم نیویورک انتخاب می‌شود.\n\n' +
            'در میان دیگر فیلم‌های بخش اصلی این دوره می‌توان به «ناگهان» ساخته ریوسوکه هاماگوچی، «میهن» ساخته پاول پاولیکوفسکی و «همیشه» ساخته ساندرا ولنر اشاره کرد که همگی پیش‌تر در جشنواره‌های کن و ونیز به نمایش درآمده بودند.',
        date: '1405-07-19',
