        content:
            'در فراخوان یکی از دوره‌های اخیر جشنواره بین‌المللی فیلم کوتاه تهران، انجمن سینمای جوانان ایران از معرفی جایزه‌ای تازه با نام «افق‌های نوظهور» خبر داد؛ بخشی که به‌طور خاص به نخستین یا دومین فیلم کوتاه داستانی فیلم‌سازان منطقه خاورمیانه و شمال آفریقا اختصاص دارد. هدف از راه‌اندازی این بخش، فراهم‌کردن بستری تازه برای معرفی صداهای نوظهور این منطقه پویا از سینمای جهان عنوان شده است.\\n\\n' +
            'جشنواره فیلم کوتاه تهران که در دو بخش ملی و بین‌الملل برگزار می‌شود، سال‌هاست یکی از مهم‌ترین رویدادهای شناسایی و معرفی فیلم‌سازان کوتاه ایران و منطقه به شمار می‌رود؛ افزوده‌شدن جایزه‌ای منطقه‌ای مانند «افق‌های نوظهور» می‌تواند جایگاه بین‌المللی این جشنواره را در میان رویدادهای مشابه در خاورمیانه و شمال آفریقا تقویت کند.',
